{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  let d = [];

  try {
    await page.evaluateOnNewDocument(() => {
      Object.defineProperty(navigator, 'webdriver', { get: () => false });
      window.chrome = { runtime: {} };
    });
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');
    await page.setViewport({ width: 1280, height: 800 });

    // LOGIN - minimal waits
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'domcontentloaded', timeout: 15000 });
    await w(500);
    const eInp = await page.$('#email_principal');
    if (eInp) { await eInp.type(EMAIL, { delay: 5 }); }
    await w(200);
    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email')); if(b) b.click(); });
    await w(1500);
    const pwd = await page.$('#pwdInput');
    if (pwd) { await pwd.type(SENHA, { delay: 5 }); }
    await w(200);
    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Entrar'); if(b) b.click(); });
    await w(2000);
    d.push('L');

    // PRODUTO
    await page.goto('https://app.cotadorsimplificado.com.br/?produto=hap', { waitUntil: 'domcontentloaded', timeout: 15000 });
    await w(1500);
    d.push('P');

    // PME
    await page.evaluate(() => { const p = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29')); if(p) p.click(); });
    await w(1000);
    d.push('M');

    // NOME + AVANCAR 1
    const nInp = await page.$('#id-nomelead');
    if (nInp) { await nInp.type('teste', { delay: 5 }); }
    await w(300);
    await page.evaluate(() => { const btns = document.querySelectorAll('button'); for(const b of btns) { const s = getComputedStyle(b); if(b.textContent.includes('Avan') && s.display !== 'none' && s.visibility !== 'hidden') { b.click(); break; } } });
    await w(1500);
    d.push('1');

    // CIDADE
    const cInp = await page.$('#cidade_nome');
    if (cInp) { await cInp.type('teresina', { delay: 30 }); }
    await w(800);
    const tc = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { if(el.textContent.trim() === 'Teresina - PI') { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2}; } } return null; });
    if (tc) await page.mouse.click(tc.x, tc.y);
    await w(500);
    d.push('C');

    // MEI + AVANCAR 2
    try { await page.select('select.Dropdown', '"mei___empres_rio_individual"'); } catch(e) {}
    await w(300);
    await page.evaluate(() => { const btns = document.querySelectorAll('button'); for(const b of btns) { const s = getComputedStyle(b); if(b.textContent.includes('Avan') && s.display !== 'none' && s.visibility !== 'hidden') { b.click(); break; } } });
    await w(1500);
    d.push('2');

    // FAIXAS + AVANCAR 3
    await page.evaluate(() => { document.querySelectorAll('input').forEach(inp => { const r = inp.getBoundingClientRect(); const s = getComputedStyle(inp); if(r.width > 0 && s.display !== 'none' && !inp.id && inp.placeholder === '0' && inp.className.includes('cocys')) { inp.value = '1'; inp.dispatchEvent(new Event('input', {bubbles:true})); inp.dispatchEvent(new Event('change', {bubbles:true})); } }); });
    await w(500);
    await page.evaluate(() => { const btns = document.querySelectorAll('button'); for(const b of btns) { const s = getComputedStyle(b); if(b.textContent.includes('Avan') && s.display !== 'none' && s.visibility !== 'hidden') { b.click(); break; } } });
    await w(2000);
    d.push('3');

    // ADD PRODUTOS
    await page.evaluate(() => { const btns = document.querySelectorAll('button'); for(const b of btns) { const s = getComputedStyle(b); if(b.textContent.trim() === 'Add Produtos' && s.display !== 'none') { b.click(); break; } } });
    await w(1500);
    d.push('A');

    // HAPVIDA
    const hc = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { if(el.textContent.trim() === 'Hapvida') { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2}; } } return null; });
    if (hc) await page.mouse.click(hc.x, hc.y);
    await w(1500);
    d.push('H');

    // TABELA
    const tb = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { const t = el.textContent.trim(); if(t.includes('Teresina') && t.includes('2') && t.includes('29')) { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2}; } } return null; });
    if (tb) await page.mouse.click(tb.x, tb.y);
    await w(1000);
    d.push('T');

    // AMBULATORIAL
    const ab = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { if(el.textContent.trim() === 'Ambulatorial') { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2}; } } return null; });
    if (ab) await page.mouse.click(ab.x, ab.y);
    await w(800);
    d.push('B');

    // ACOMODACAO
    const ac = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { const t = el.textContent.trim().toLowerCase(); if(t.includes('sem acomod') && t.includes('copartic')) { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2}; } } return null; });
    if (ac) await page.mouse.click(ac.x, ac.y);
    await w(800);
    d.push('O');

    // FECHA + EXTRAI
    await page.mouse.click(1200, 400);
    await w(1500);
    d.push('X');

    const faixas = await page.evaluate(() => { const nomes = ['0 a 18 anos','19 a 23 anos','24 a 28 anos','29 a 33 anos','34 a 38 anos','39 a 43 anos','44 a 48 anos','49 a 53 anos','54 a 58 anos','59 anos ou mais']; const vals = []; const regex = /^\d{2,3}[,.]\d{2}$/; document.querySelectorAll('div, span').forEach(el => { const s = getComputedStyle(el); const r = el.getBoundingClientRect(); if(s.display !== 'none' && r.width > 0 && el.textContent.length < 15) { const t = el.textContent.trim(); if(regex.test(t) && !vals.some(v => v.text === t) && r.y > 650 && r.x > 150 && r.x < 280) { vals.push({text: t, y: r.y}); } } }); vals.sort((a,b) => a.y - b.y); return vals.slice(0,10).map((v,i) => ({faixa_etaria: nomes[i], valor: 'R$ ' + v.text.replace('.',',')})); });
    d.push('V' + faixas.length);

    return { success: true, debug: d.join('-'), faixas };
  } catch (error) {
    return { success: false, error: error.message, debug: d.join('-') };
  }
}"
}
